CREATE TABLE oauth_logins(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,state_digest TEXT NOT NULL CHECK(length(state_digest)=64),nonce_digest TEXT NOT NULL CHECK(length(nonce_digest)=64),verifier_digest TEXT NOT NULL CHECK(length(verifier_digest)=64),actor_id TEXT NOT NULL,actor_epoch BIGINT NOT NULL CHECK(actor_epoch>=0),expires_at_ms BIGINT NOT NULL,consumed BOOLEAN NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,state_digest),FOREIGN KEY(organization_id,tenant_id,actor_id) REFERENCES principals(organization_id,tenant_id,subject_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX oauth_expiry ON oauth_logins(organization_id,tenant_id,expires_at_ms);
ALTER TABLE oauth_logins ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_logins FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON oauth_logins USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
